(function(){
  "use strict";

  /* ============================================================
     DATOS DE PRODUCTOS (en un sitio real vendrían del backend)
     ============================================================ */
  var IMG = ["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,",
             "data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"];

  // 12 productos principales (coinciden con la maqueta)
  var base = [
    {nombre:"Aceite vegetal 1L",     precio:45.90, anterior:65.00, cat:"alimentos", disp:true,  img:0},
    {nombre:"Leche entera 1L",       precio:28.50, anterior:34.00, cat:"alimentos", disp:true,  img:1},
    {nombre:"Detergente 3kg",        precio:89.00, anterior:120.00,cat:"hogar",     disp:true,  img:2},
    {nombre:"Jamón 400g",            precio:62.00, anterior:78.00, cat:"alimentos", disp:true,  img:3},
    {nombre:"Shampoo 750ml",         precio:54.90, anterior:null,  cat:"belleza",   disp:true,  img:4},
    {nombre:"Arroz 1kg",             precio:32.00, anterior:null,  cat:"alimentos", disp:true,  img:5},
    {nombre:"Frijol negro 1kg",      precio:29.90, anterior:null,  cat:"alimentos", disp:true,  img:6},
    {nombre:"Papel higiénico 12pk",  precio:65.00, anterior:null,  cat:"hogar",     disp:true,  img:7},
    {nombre:"Jabón 3pk",             precio:42.00, anterior:null,  cat:"belleza",   disp:true,  img:8},
    {nombre:"Galletas 400g",         precio:36.50, anterior:null,  cat:"alimentos", disp:true,  img:9},
    {nombre:"Cereal 500g",           precio:58.00, anterior:null,  cat:"alimentos", disp:true,  img:10},
    {nombre:"Refresco 2L",           precio:24.00, anterior:null,  cat:"bebidas",   disp:true,  img:11}
  ];

  // Productos adicionales para que la paginación (3 páginas) sea funcional
  var extras = [
    {nombre:"Pasta dental 100ml",    precio:38.00, anterior:null,  cat:"belleza",   disp:false, img:4},
    {nombre:"Desodorante 150ml",     precio:49.50, anterior:59.00, cat:"belleza",   disp:false, img:8},
    {nombre:"Aceite de oliva 250ml", precio:82.00, anterior:95.00, cat:"alimentos", disp:true,  img:0},
    {nombre:"Leche descremada 1L",   precio:30.00, anterior:null,  cat:"alimentos", disp:true,  img:1},
    {nombre:"Detergente líquido 2L", precio:74.00, anterior:null,  cat:"hogar",     disp:true,  img:2},
    {nombre:"Jamón de pavo 300g",    precio:55.00, anterior:68.00, cat:"alimentos", disp:true,  img:3},
    {nombre:"Arroz integral 1kg",    precio:38.50, anterior:null,  cat:"alimentos", disp:true,  img:5},
    {nombre:"Frijol bayo 1kg",       precio:31.00, anterior:null,  cat:"alimentos", disp:true,  img:6},
    {nombre:"Papel de cocina 2pk",   precio:28.00, anterior:null,  cat:"hogar",     disp:true,  img:7},
    {nombre:"Galletas de avena 350g",precio:39.90, anterior:45.00, cat:"alimentos", disp:true,  img:9},
    {nombre:"Cereal integral 400g",  precio:62.00, anterior:null,  cat:"alimentos", disp:true,  img:10},
    {nombre:"Refresco naranja 2L",   precio:24.00, anterior:28.00, cat:"bebidas",   disp:true,  img:11},
    {nombre:"Agua mineral 1.5L",     precio:12.50, anterior:null,  cat:"bebidas",   disp:true,  img:11},
    {nombre:"Atún en lata 140g",     precio:18.90, anterior:null,  cat:"alimentos", disp:true,  img:3},
    {nombre:"Mayonesa 470g",         precio:33.00, anterior:39.00, cat:"alimentos", disp:true,  img:0},
    {nombre:"Catsup 700g",           precio:29.50, anterior:null,  cat:"alimentos", disp:true,  img:10},
    {nombre:"Azúcar 1kg",            precio:22.00, anterior:null,  cat:"alimentos", disp:true,  img:5},
    {nombre:"Café molido 250g",      precio:64.00, anterior:72.00, cat:"alimentos", disp:true,  img:6},
    {nombre:"Jabón líquido 500ml",   precio:48.00, anterior:null,  cat:"belleza",   disp:true,  img:4},
    {nombre:"Limpiador multiusos",   precio:36.00, anterior:null,  cat:"hogar",     disp:true,  img:2},
    {nombre:"Vino tinto 750ml",      precio:145.00,anterior:180.00,cat:"cervezas",  disp:true,  img:0},
    {nombre:"Cerveza clara 6pk",     precio:98.00, anterior:null,  cat:"cervezas",  disp:true,  img:11},
    {nombre:"Croquetas perro 2kg",   precio:189.00,anterior:210.00,cat:"mascotas",  disp:true,  img:2},
    {nombre:"Arena para gato 4kg",   precio:115.00,anterior:null,  cat:"mascotas",  disp:true,  img:7}
  ];

  var PRODUCTOS = base.concat(extras).map(function(p,i){ p.id = i+1; return p; });

  /* ============================================================
     ESTADO DE LA APLICACIÓN
     ============================================================ */
  var state = {
    categoria: "alimentos",
    minPrecio: 0,
    maxPrecio: 300,
    soloDisponibles: true,
    orden: "relevancia",
    pagina: 1,
    porPagina: 12,
    carrito: 6
  };

  var catNombres = {
    alimentos:"Alimentos", cervezas:"Cervezas, Vinos y Licores", hogar:"Hogar",
    ferreteria:"Ferretería", bebidas:"Bebidas", belleza:"Belleza y cuidado personal", mascotas:"Mascotas"
  };

  /* ============================================================
     FILTRADO + ORDENAMIENTO
     ============================================================ */
  function filtrar(){
    return PRODUCTOS.filter(function(p){
      // En la maqueta, "Alimentos" muestra productos variados, así que la
      // categoría es navegación visual. Para filtrar de verdad, descomenta:
      // if (state.categoria && p.cat !== state.categoria) return false;
      if (p.precio < state.minPrecio || p.precio > state.maxPrecio) return false;
      if (state.soloDisponibles && !p.disp) return false;
      return true;
    });
  }

  function ordenar(lista){
    var l = lista.slice();
    if (state.orden === "precio-asc")  l.sort(function(a,b){ return a.precio - b.precio; });
    if (state.orden === "precio-desc") l.sort(function(a,b){ return b.precio - a.precio; });
    if (state.orden === "nombre")      l.sort(function(a,b){ return a.nombre.localeCompare(b.nombre, "es"); });
    return l;
  }

  /* ============================================================
     RENDERIZADO DE TARJETAS
     ============================================================ */
  var grid = document.getElementById("productGrid");
  var emptyState = document.getElementById("emptyState");
  var foundCount = document.getElementById("foundCount");
  var catTitle = document.getElementById("catTitle");

  function fmt(n){ return "$" + n.toFixed(2).replace(".",","); }

  function render(){
    var lista = ordenar(filtrar());
    var total = lista.length;
    var totalPag = Math.max(1, Math.ceil(total / state.porPagina));
    if (state.pagina > totalPag) state.pagina = totalPag;
    var inicio = (state.pagina - 1) * state.porPagina;
    var pagina = lista.slice(inicio, inicio + state.porPagina);

    catTitle.textContent = catNombres[state.categoria] || "Productos";
    foundCount.textContent = "(" + total + " productos encontrados)";

    if (total === 0){
      grid.innerHTML = "";
      emptyState.classList.remove("d-none");
    } else {
      emptyState.classList.add("d-none");
      var html = "";
      pagina.forEach(function(p, idx){
        var oferta = p.anterior ? '<span class="oferta-tag">OFERTA</span>' : '';
        var precioAnt = p.anterior ? '<span class="price-old">' + fmt(p.anterior) + '</span>' : '';
        var stock = p.disp
          ? '<span class="stock-badge in"><i class="bi bi-check-circle-fill"></i>Disponible</span>'
          : '<span class="stock-badge out"><i class="bi bi-x-circle-fill"></i>Agotado</span>';
        var btn = p.disp
          ? '<button class="add-btn" data-id="'+p.id+'" aria-label="Añadir '+p.nombre+'"><i class="bi bi-plus-lg"></i></button>'
          : '';
        html +=
        '<div class="col-6 col-md-4 col-lg-3 card-anim" style="animation-delay:'+(idx*0.035)+'s">'+
          '<div class="product-card">'+
            '<div class="product-img-wrap">'+
              oferta + btn +
              '<img src="'+IMG[p.img]+'" alt="'+p.nombre+'" loading="lazy" onerror="this.style.display=\'none\'">'+
            '</div>'+
            '<div class="product-body">'+
              stock +
              '<div class="product-name">'+p.nombre+'</div>'+
              '<div class="price-row"><span class="price-now">'+fmt(p.precio)+'</span>'+precioAnt+'</div>'+
            '</div>'+
          '</div>'+
        '</div>';
      });
      grid.innerHTML = html;
    }
    renderPaginacion(totalPag);
  }

  /* ============================================================
     PAGINACIÓN
     ============================================================ */
  var pag = document.getElementById("pagination");
  function renderPaginacion(totalPag){
    var html = "";
    html += '<li class="page-item '+(state.pagina===1?"disabled":"")+'"><a class="page-link" href="#" data-page="'+(state.pagina-1)+'"><i class="bi bi-chevron-left"></i></a></li>';
    for (var i=1; i<=totalPag; i++){
      html += '<li class="page-item '+(i===state.pagina?"active":"")+'"><a class="page-link" href="#" data-page="'+i+'">'+i+'</a></li>';
    }
    html += '<li class="page-item '+(state.pagina===totalPag?"disabled":"")+'"><a class="page-link" href="#" data-page="'+(state.pagina+1)+'"><i class="bi bi-chevron-right"></i></a></li>';
    pag.innerHTML = html;
  }

  pag.addEventListener("click", function(e){
    var a = e.target.closest("a[data-page]");
    if (!a) return;
    e.preventDefault();
    if (a.parentElement.classList.contains("disabled")) return;
    state.pagina = parseInt(a.dataset.page, 10);
    render();
    window.scrollTo({top:0, behavior:"smooth"});
  });

  /* ============================================================
     CATEGORÍAS (sidebar)
     ============================================================ */
  document.getElementById("catList").addEventListener("click", function(e){
    var li = e.target.closest("li[data-cat]");
    if (!li) return;
    this.querySelectorAll("li").forEach(function(x){ x.classList.remove("active"); });
    li.classList.add("active");
    state.categoria = li.dataset.cat;
    state.pagina = 1;
    render();
    // Cerrar panel de filtros en móvil tras elegir categoría
    if (window.innerWidth < 992){
      var col = bootstrap.Collapse.getInstance(document.getElementById("filterCollapse"));
      if (col) col.hide();
    }
  });

  /* ============================================================
     RANGO DE PRECIO (slider doble + inputs numéricos sincronizados)
     ============================================================ */
  var minRange = document.getElementById("minRange");
  var maxRange = document.getElementById("maxRange");
  var minInput = document.getElementById("minInput");
  var maxInput = document.getElementById("maxInput");
  var rangeFill = document.getElementById("rangeFill");
  var MAX = 300, GAP = 5;

  function actualizarRangoUI(){
    var l = (state.minPrecio / MAX) * 100;
    var r = 100 - (state.maxPrecio / MAX) * 100;
    rangeFill.style.left = l + "%";
    rangeFill.style.right = r + "%";
    minInput.value = state.minPrecio;
    maxInput.value = state.maxPrecio;
    minRange.value = state.minPrecio;
    maxRange.value = state.maxPrecio;
  }

  function enCambioPrecio(){
    var mn = parseInt(minRange.value, 10);
    var mx = parseInt(maxRange.value, 10);
    if (mn > mx - GAP){ // evitar cruce
      if (this === minRange) { mn = mx - GAP; minRange.value = mn; }
      else { mx = mn + GAP; maxRange.value = mx; }
    }
    state.minPrecio = mn;
    state.maxPrecio = mx;
    actualizarRangoUI();
    state.pagina = 1;
    render();
  }
  minRange.addEventListener("input", enCambioPrecio);
  maxRange.addEventListener("input", enCambioPrecio);

  function enCambioInput(){
    var mn = Math.max(0, Math.min(MAX, parseInt(minInput.value,10) || 0));
    var mx = Math.max(0, Math.min(MAX, parseInt(maxInput.value,10) || MAX));
    if (mn > mx) mn = mx;
    state.minPrecio = mn; state.maxPrecio = mx;
    actualizarRangoUI();
    state.pagina = 1;
    render();
  }
  minInput.addEventListener("change", enCambioInput);
  maxInput.addEventListener("change", enCambioInput);

  /* ============================================================
     DISPONIBILIDAD + ORDENAMIENTO
     ============================================================ */
  document.getElementById("stockToggle").addEventListener("change", function(){
    state.soloDisponibles = this.checked;
    state.pagina = 1;
    render();
  });
  document.getElementById("sortSelect").addEventListener("change", function(){
    state.orden = this.value;
    state.pagina = 1;
    render();
  });

  /* ============================================================
     AÑADIR AL CARRITO (delegación de eventos + animación)
     ============================================================ */
  var cartBadge = document.getElementById("cartBadge");
  var toast = document.getElementById("toastCart");
  var toastText = document.getElementById("toastText");
  var toastTimer = null;

  grid.addEventListener("click", function(e){
    var btn = e.target.closest(".add-btn");
    if (!btn) return;
    state.carrito++;
    cartBadge.textContent = state.carrito;
    cartBadge.classList.remove("pop");
    void cartBadge.offsetWidth; // reiniciar animación
    cartBadge.classList.add("pop");

    // Botón pasa a check verde momentáneamente
    btn.classList.add("added");
    btn.innerHTML = '<i class="bi bi-check-lg"></i>';
    setTimeout(function(){
      btn.classList.remove("added");
      btn.innerHTML = '<i class="bi bi-plus-lg"></i>';
    }, 900);

    // Toast de confirmación
    var prod = PRODUCTOS.find(function(p){ return p.id === parseInt(btn.dataset.id,10); });
    toastText.textContent = (prod ? prod.nombre : "Producto") + " añadido al carrito";
    toast.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function(){ toast.classList.remove("show"); }, 1800);
  });

  /* ============================================================
     INICIO
     ============================================================ */
  actualizarRangoUI();
  render();
})();
